window.REPLIKEN = [{"nr": 1, "speaker": "PF", "phase": "Einstieg", "a": 10.0, "b": 13.52, "lines": [{"a": 10.0, "b": 11.52, "text": "Guten Morgen, Sami."}, {"a": 11.52, "b": 13.67, "text": "Darf ich mich kurz zu Ihnen setzen?"}]}, {"nr": 2, "speaker": "P", "phase": "Einstieg", "a": 13.92, "b": 18.48, "lines": [{"a": 14.36, "b": 16.38, "text": "Ja, setzen Sie sich."}, {"a": 16.38, "b": 18.63, "text": "Sie sind doch die aus der Nachbarschaft, oder?"}]}, {"nr": 3, "speaker": "PF", "phase": "Einstieg", "a": 18.88, "b": 25.6, "lines": [{"a": 19.14, "b": 23.6, "text": "Genau. Ich bin Takiyat, Pflegefachfrau in Ausbildung."}, {"a": 23.6, "b": 25.75, "text": "Wie geht es Ihnen heute mit der Luft?"}]}, {"nr": 4, "speaker": "P", "phase": "Einstieg", "a": 26.0, "b": 31.04, "lines": [{"a": 26.82, "b": 31.19, "text": "Geht so. Ohne den Sauerstoff zwischendurch komme ich nicht weit."}]}, {"nr": 5, "speaker": "PF", "phase": "Einstieg", "a": 31.44, "b": 41.04, "lines": [{"a": 31.52, "b": 35.88, "text": "Bei der Morgenpflege habe ich die Zigaretten in Ihrem Nachtschrank gesehen."}, {"a": 35.88, "b": 38.3, "text": "Ich möchte Ihnen keine Vorwürfe machen."}, {"a": 38.3, "b": 41.19, "text": "Dürfte ich trotzdem kurz mit Ihnen darüber sprechen?"}]}, {"nr": 6, "speaker": "P", "phase": "Einstieg", "a": 41.44, "b": 46.64, "lines": [{"a": 41.68, "b": 43.38, "text": "Wenn's sein muss."}, {"a": 43.38, "b": 46.79, "text": "Mein Arzt erzählt mir schon seit Jahren, dass ich damit aufhören soll."}]}, {"nr": 7, "speaker": "PF", "phase": "Ask", "a": 47.44, "b": 51.44, "lines": [{"a": 47.44, "b": 49.28, "text": "Dann frage ich einfach mal:"}, {"a": 49.28, "b": 51.59, "text": "Wie viel rauchen Sie zurzeit am Tag?"}]}, {"nr": 8, "speaker": "P", "phase": "Ask", "a": 51.84, "b": 55.28, "lines": [{"a": 51.84, "b": 55.43, "text": "Eine Schachtel. Beim Skat am Wochenende auch mehr."}]}, {"nr": 9, "speaker": "PF", "phase": "Ask", "a": 55.68, "b": 57.52, "lines": [{"a": 55.68, "b": 57.67, "text": "Und seit wann rauchen Sie?"}]}, {"nr": 10, "speaker": "P", "phase": "Ask", "a": 57.92, "b": 61.04, "lines": [{"a": 58.9, "b": 61.19, "text": "Seit über vierzig Jahren."}]}, {"nr": 11, "speaker": "PF", "phase": "Advise", "a": 61.84, "b": 77.36, "lines": [{"a": 61.96, "b": 63.84, "text": "Danke für Ihre Offenheit."}, {"a": 63.84, "b": 66.18, "text": "Ich sage Ihnen ehrlich, was ich denke:"}, {"a": 66.18, "b": 71.48, "text": "Mit dem Rauchen aufzuhören ist das Wichtigste, was Sie bei COPD für Ihre Lunge tun können."}, {"a": 71.48, "b": 74.2, "text": "Der Schaden, der schon da ist, geht nicht mehr weg."}, {"a": 74.2, "b": 77.51, "text": "Aber ohne Rauch schreitet die Krankheit langsamer voran."}]}, {"nr": 12, "speaker": "P", "phase": "Advise", "a": 77.76, "b": 85.36, "lines": [{"a": 77.8, "b": 82.38, "text": "Ach was. Von meinen Skatbrüdern rauchen auch alle, und krank ist keiner."}, {"a": 82.38, "b": 85.51, "text": "Der Martin ist letztes Jahr sogar einen Halbmarathon gelaufen."}]}, {"nr": 13, "speaker": "PF", "phase": "Advise", "a": 85.76, "b": 94.72, "lines": [{"a": 85.82, "b": 89.06, "text": "Sie sehen bei Ihren Freunden, dass es auch anders gehen kann."}, {"a": 89.06, "b": 91.0, "text": "Jede Lunge reagiert anders."}, {"a": 91.0, "b": 94.87, "text": "Ihre Lunge ist schon krank, und das merken Sie jeden Tag beim Atmen."}]}, {"nr": 14, "speaker": "P", "phase": "Advise", "a": 95.12, "b": 98.72, "lines": [{"a": 95.22, "b": 98.87, "text": "Ja … die Treppe zu meiner Wohnung schaffe ich kaum noch."}]}, {"nr": 15, "speaker": "PF", "phase": "Advise", "a": 99.12, "b": 106.8, "lines": [{"a": 99.24, "b": 102.7, "text": "Noch etwas ist mir wichtig, weil Sie Sauerstoff bekommen:"}, {"a": 102.7, "b": 106.95, "text": "In der Nähe von Sauerstoff zu rauchen ist gefährlich, es kann schnell brennen."}]}, {"nr": 16, "speaker": "P", "phase": "Advise", "a": 107.2, "b": 109.36, "lines": [{"a": 107.24, "b": 109.51, "text": "Daran habe ich gar nicht gedacht."}]}, {"nr": 17, "speaker": "PF", "phase": "Assess", "a": 110.16, "b": 115.44, "lines": [{"a": 110.16, "b": 112.84, "text": "Darf ich Ihnen zwei kurze Fragen stellen?"}, {"a": 112.84, "b": 115.59, "text": "Wann rauchen Sie morgens die erste Zigarette?"}]}, {"nr": 18, "speaker": "P", "phase": "Assess", "a": 115.84, "b": 119.28, "lines": [{"a": 115.84, "b": 117.66, "text": "Direkt nach dem Aufstehen."}, {"a": 117.66, "b": 119.43, "text": "Sonst komme ich nicht in Gang."}]}, {"nr": 19, "speaker": "PF", "phase": "Assess", "a": 119.68, "b": 125.84, "lines": [{"a": 119.66, "b": 123.92, "text": "Und fällt es Ihnen schwer, dort nicht zu rauchen, wo es verboten ist?"}, {"a": 123.92, "b": 125.99, "text": "Hier im Krankenhaus zum Beispiel?"}]}, {"nr": 20, "speaker": "P", "phase": "Assess", "a": 126.24, "b": 131.36, "lines": [{"a": 126.4, "b": 129.04, "text": "Ehrlich gesagt, ja."}, {"a": 129.04, "b": 131.51, "text": "Deshalb liegt die Schachtel ja im Nachtschrank."}]}, {"nr": 21, "speaker": "PF", "phase": "Assess", "a": 131.76, "b": 145.28, "lines": [{"a": 131.8, "b": 135.26, "text": "Das spricht für eine deutliche körperliche Abhängigkeit."}, {"a": 135.26, "b": 140.14, "text": "Das ist keine Willensschwäche, sondern eine Abhängigkeit, die man gut behandeln kann."}, {"a": 140.14, "b": 142.44, "text": "Auf einer Skala von null bis zehn:"}, {"a": 142.44, "b": 145.43, "text": "Wie wichtig ist es Ihnen gerade, etwas zu verändern?"}]}, {"nr": 22, "speaker": "P", "phase": "Assess", "a": 145.68, "b": 151.04, "lines": [{"a": 145.88, "b": 148.1, "text": "Vielleicht eine Vier."}, {"a": 148.1, "b": 149.46, "text": "Wegen meiner Frau."}, {"a": 149.46, "b": 151.19, "text": "Die macht sich große Sorgen."}]}, {"nr": 23, "speaker": "PF", "phase": "Assess", "a": 151.44, "b": 154.16, "lines": [{"a": 151.44, "b": 154.31, "text": "Eine Vier. Und warum keine Zwei?"}]}, {"nr": 24, "speaker": "P", "phase": "Assess", "a": 154.56, "b": 158.24, "lines": [{"a": 154.56, "b": 157.42, "text": "Weil ich wieder ohne Pause zur Kneipe laufen will."}, {"a": 157.42, "b": 158.39, "text": "Zum Skat."}]}, {"nr": 25, "speaker": "PF", "phase": "Assist", "a": 159.04, "b": 172.72, "lines": [{"a": 159.12, "b": 160.78, "text": "Das sind gute Gründe."}, {"a": 160.78, "b": 162.88, "text": "Sie müssen heute nichts entscheiden."}, {"a": 162.88, "b": 167.18, "text": "Wenn Sie möchten, spreche ich mit der Ärztin über eine Nikotinersatztherapie,"}, {"a": 167.18, "b": 168.88, "text": "zum Beispiel ein Pflaster."}, {"a": 168.88, "b": 172.87, "text": "Das lindert die Entzugserscheinungen, hier im Krankenhaus und danach."}]}, {"nr": 26, "speaker": "P", "phase": "Assist", "a": 173.12, "b": 175.92, "lines": [{"a": 173.16, "b": 176.07, "text": "Und beim Skat? Da raucht doch jeder."}]}, {"nr": 27, "speaker": "PF", "phase": "Assist", "a": 176.32, "b": 185.6, "lines": [{"a": 176.26, "b": 179.46, "text": "Genau das ist eine schwierige Situation."}, {"a": 179.46, "b": 182.78, "text": "Dafür gibt es Nikotinkaugummis für starke Momente."}, {"a": 182.78, "b": 185.75, "text": "Und vielleicht kann Ihre Frau Sie dabei unterstützen."}]}, {"nr": 28, "speaker": "P", "phase": "Assist", "a": 186.0, "b": 189.28, "lines": [{"a": 186.14, "b": 187.78, "text": "Die würde sich freuen."}, {"a": 187.78, "b": 189.43, "text": "Die sagt das schon lange."}]}, {"nr": 29, "speaker": "PF", "phase": "Assist", "a": 189.68, "b": 200.72, "lines": [{"a": 189.68, "b": 193.62, "text": "Dazu gibt es eine kostenlose Telefonberatung zum Rauchstopp."}, {"a": 193.62, "b": 198.18, "text": "Dort ruft man Sie auf Wunsch zurück und begleitet Sie auch nach der Entlassung."}, {"a": 198.18, "b": 200.87, "text": "Ich gebe Ihnen ein Infoblatt mit allen Nummern."}]}, {"nr": 30, "speaker": "P", "phase": "Assist", "a": 201.12, "b": 205.2, "lines": [{"a": 201.22, "b": 205.35, "text": "Auf einen Schlag aufhören … das schaffe ich nicht."}]}, {"nr": 31, "speaker": "PF", "phase": "Assist", "a": 205.6, "b": 211.52, "lines": [{"a": 205.62, "b": 207.84, "text": "Dann gehen wir es Schritt für Schritt an."}, {"a": 207.84, "b": 211.67, "text": "Wären Sie bereit, das Pflaster hier im Krankenhaus auszuprobieren?"}]}, {"nr": 32, "speaker": "P", "phase": "Assist", "a": 211.92, "b": 214.32, "lines": [{"a": 212.12, "b": 214.47, "text": "Ausprobieren kann ich es ja mal."}]}, {"nr": 33, "speaker": "PF", "phase": "Arrange", "a": 215.12, "b": 228.32, "lines": [{"a": 215.16, "b": 218.16, "text": "Das freut mich. Dann halten wir fest:"}, {"a": 218.16, "b": 221.02, "text": "Ich spreche heute mit der Ärztin über das Pflaster."}, {"a": 221.02, "b": 222.8, "text": "Sie bekommen das Infoblatt."}, {"a": 222.8, "b": 227.18, "text": "Und morgen früh setze ich mich wieder zu Ihnen, und wir schauen, wie es Ihnen damit geht."}, {"a": 227.18, "b": 228.47, "text": "Passt das für Sie?"}]}, {"nr": 34, "speaker": "P", "phase": "Arrange", "a": 228.72, "b": 233.28, "lines": [{"a": 228.72, "b": 233.43, "text": "Ja. Und die Zigaretten … die kann meine Frau nachher mitnehmen."}]}, {"nr": 35, "speaker": "PF", "phase": "Arrange", "a": 233.68, "b": 239.2, "lines": [{"a": 233.72, "b": 235.78, "text": "Das ist ein guter erster Schritt."}, {"a": 235.78, "b": 238.08, "text": "Sie entscheiden, ich begleite Sie."}, {"a": 238.08, "b": 239.35, "text": "Bis morgen, Sami."}]}];
